pages.script:
function pageEnter() {
  store.set('where', page.name)
  if (store.get('lastEvent') === undefined) store.set('lastEvent', '—')
}

function pageEnter() {
  store.set('where', page.name)
  if (store.get('midiInfo') === undefined) store.set('midiInfo', 'nothing built yet — press a button')
  if (store.get('playInfo') === undefined) store.set('playInfo', '')
}

// One shared source of truth: the same two-note MIDI (C4, then E4) fuels every
// demo below. addNote takes a midi note number, time/duration in seconds, and
// velocity 0..1. Imports resolve via esm.sh (or the shelf — offline books).
async function buildMidi() {
  const { Midi } = await import('@tonejs/midi')
  const midi = new Midi()
  const track = midi.addTrack()
  track.name = 'toolback demo'
  track.addNote({ midi: 60, time: 0, duration: 0.5, velocity: 0.8 })
  track.addNote({ midi: 64, time: 0.5, duration: 0.5, velocity: 0.8 })
  return midi
}

// Data path: @tonejs/midi is a data library — build, serialize with
// midi.toArray(), re-parse. No files, no sound, no servers.
async function parseDemo() {
  const midi = await buildMidi()
  const { Midi } = await import('@tonejs/midi')
  const reparsed = new Midi(midi.toArray())
  const track = reparsed.tracks[0]
  store.set('midiInfo', `tracks: ${reparsed.tracks.length}, notes: ${track.notes.length} — ${track.notes.map((n) => n.name).join(' + ')}`)
}

// Audio path: the notes are data, so Tone.js makes them audible. Browsers
// require a user gesture before audio starts — a button click is one.
async function playDemo() {
  store.set('playInfo', 'starting audio…')
  const Tone = await import('tone')
  const track = (await buildMidi()).tracks[0]

  await Tone.start() // unlock the AudioContext
  const synth = new Tone.PolySynth(Tone.Synth).toDestination()
  const when = Tone.now() + 0.1 // tiny delay so both notes land cleanly
  for (const note of track.notes) {
    synth.triggerAttackRelease(note.name, note.duration, note.time + when, note.velocity)
  }
  store.set('playInfo', `playing ${track.notes.map((n) => n.name).join(' + ')}`)

  // Dispose the synth after the last note has rung out.
  const last = track.notes[track.notes.length - 1]
  setTimeout(() => {
    synth.dispose()
    store.set('playInfo', 'done')
  }, (last.time + last.duration + 0.5) * 1000)
}

// File path: midi.toArray() is the raw bytes — wrap them in a Blob and click a
// temporary <a download> link. The same pattern exports any binary payload.
async function downloadDemo() {
  const midi = await buildMidi()
  const bytes = midi.toArray()
  const blob = new Blob([bytes], { type: 'audio/midi' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = 'toolback_demo.mid'
  document.body.appendChild(a)
  a.click()
  a.remove()
  URL.revokeObjectURL(url)
  store.set('midiInfo', `downloaded toolback_demo.mid — ${bytes.length} bytes`)
  store.set('playInfo', 'saved toolback_demo.mid')
}

function pageEnter() {
  store.set('where', page.name)
  if (store.get('demoScore') === undefined) store.set('demoScore', 0)
}

