on.draw:
const ctx = self.ctx
const w = self.width, h = self.height
const t = performance.now() / 500
ctx.fillStyle = '#0f172a'
ctx.fillRect(0, 0, w, h)
const colors = ['#38bdf8', '#a78bfa', '#f472b6']
for (let k = 0; k < 3; k++) {
  ctx.beginPath()
  ctx.lineWidth = 2
  ctx.strokeStyle = colors[k]
  for (let x = 0; x <= w; x += 2) {
    const y = h / 2 + Math.sin(x / 28 + t + k * 1.3) * (h / 5)
    if (x === 0) ctx.moveTo(x, y)
    else ctx.lineTo(x, y)
  }
  ctx.stroke()
}
